/// `z <- 1 / x mod p` (`0` for `x = 0`). `h`, if given, is the precomputed
/// progenitor `x^((p-3)/4)`.
#[inline]
pub(crate) fn modinv(z: &mut [u64; NLIMBS], x: &[u64; NLIMBS], h: Option<&[u64; NLIMBS]>) {
    let mut t = [0u64; NLIMBS];
    match h {
        None => modpro(&mut t, x),
        Some(h) => t = *h,
    }
    modnsqr(&mut t, 2);
    modmul(z, x, &t);
}

/// Canonical integer to Montgomery form.
#[inline]
pub(crate) fn nres(n: &mut [u64; NLIMBS], m: &[u64; NLIMBS]) {
    modmul(n, m, &R2_NRES);
}

/// Montgomery form to canonical integer in `[0, p)`.
#[inline]
pub(crate) fn redc(m: &mut [u64; NLIMBS], n: &[u64; NLIMBS]) {
    let mut c = [0u64; NLIMBS];
    c[0] = 1;
    modmul(m, n, &c);
    let _ = modfsb(m);
}

/// `1` if `a == 0 mod p`, else `0`.
#[inline]
pub(crate) fn modis0(a: &[u64; NLIMBS]) -> u32 {
    let mut c = [0u64; NLIMBS];
    redc(&mut c, a);
    let mut d: u64 = 0;
    for limb in c.iter() {
        d |= *limb;
    }
    (1 & (d.wrapping_sub(1) >> RADIX)) as u32
}

/// `1` if `a == 1 mod p`, else `0`.
#[inline]
pub(crate) fn modis1(a: &[u64; NLIMBS]) -> u32 {
    let mut c = [0u64; NLIMBS];
    redc(&mut c, a);
    let mut d: u64 = 0;
    for limb in c.iter().skip(1) {
        d |= *limb;
    }
    (1 & (d.wrapping_sub(1) >> RADIX) & ((c[0] ^ 1).wrapping_sub(1) >> RADIX)) as u32
}

/// `1` if `a == b mod p`, else `0`.
#[inline]
pub(crate) fn modcmp(a: &[u64; NLIMBS], b: &[u64; NLIMBS]) -> u32 {
    let mut c = [0u64; NLIMBS];
    let mut d = [0u64; NLIMBS];
    redc(&mut c, a);
    redc(&mut d, b);
    let mut eq: u64 = 1;
    for i in 0..NLIMBS {
        eq &= (c[i] ^ d[i]).wrapping_sub(1) >> RADIX;
    }
    (eq & 1) as u32
}

/// `1` if `x` is a square (or zero), else `0`. `h` is the optional
/// precomputed progenitor.
#[inline]
pub(crate) fn modqr(x: &[u64; NLIMBS], h: Option<&[u64; NLIMBS]>) -> u32 {
    let mut r = [0u64; NLIMBS];
    match h {
        None => {
            let mut pro = [0u64; NLIMBS];
            modpro(&mut pro, x);
            modsqr(&mut r, &pro);
        }
        Some(h) => modsqr(&mut r, h),
    }
    mul_assign(&mut r, x);
    modis1(&r) | modis0(x)
}

/// `r <- sqrt(x)` for square `x` (`x^((p+1)/4)`), defined up to sign.
#[inline]
pub(crate) fn modsqrt(r: &mut [u64; NLIMBS], x: &[u64; NLIMBS], h: Option<&[u64; NLIMBS]>) {
    let mut y = [0u64; NLIMBS];
    match h {
        None => modpro(&mut y, x),
        Some(h) => y = *h,
    }
    modmul(r, &y, x);
}

/// `a <- x` in Montgomery form.
#[inline]
pub(crate) fn modint(a: &mut [u64; NLIMBS], x: u64) {
    let mut m = [0u64; NLIMBS];
    m[0] = x;
    nres(a, &m);
}

/// `c <- a * x mod 2p` for a small integer `x`.
#[inline]
pub(crate) fn modmli(c: &mut [u64; NLIMBS], a: &[u64; NLIMBS], x: u64) {
    let mut t = [0u64; NLIMBS];
    modint(&mut t, x);
    modmul(c, a, &t);
}

/// Shift left by `n < RADIX` bits, carrying into the next limb.
#[inline]
pub(crate) fn modshl(a: &mut [u64; NLIMBS], n: u32) {
    a[10] = (a[10] << n) | (a[9] >> (RADIX - n));
    for i in (1..10).rev() {
        a[i] = ((a[i] << n) & MASK) | (a[i - 1] >> (RADIX - n));
    }
    a[0] = (a[0] << n) & MASK;
}

/// Shift right by `n < RADIX` bits, returning the bits shifted out.
#[inline]
pub(crate) fn modshr(a: &mut [u64; NLIMBS], n: u32) -> u64 {
    let r = a[0] & ((1u64 << n) - 1);
    for i in 0..10 {
        a[i] = (a[i] >> n) | ((a[i + 1] << (RADIX - n)) & MASK);
    }
    a[10] >>= n;
    r
}

/// Constant-time conditional swap of `f` and `g` when `b == 1`.
#[inline]
pub(crate) fn modcsw(b: u64, g: &mut [u64; NLIMBS], f: &mut [u64; NLIMBS]) {
    let r: u64 = 0x3cc3_c33c_5aa5_a55a;
    let c0 = (1u64.wrapping_sub(b)).wrapping_add(r);
    let c1 = b.wrapping_add(r);
    for i in 0..NLIMBS {
        let s = g[i];
        let t = f[i];
        let w = r.wrapping_mul(t.wrapping_add(s));
        f[i] = c0
            .wrapping_mul(t)
            .wrapping_add(c1.wrapping_mul(s))
            .wrapping_sub(w);
        g[i] = c0
            .wrapping_mul(s)
            .wrapping_add(c1.wrapping_mul(t))
            .wrapping_sub(w);
    }
}

/// Canonical little-endian encoding of `a` into `ENCODED_BYTES` bytes.
#[inline]
pub(crate) fn fp_encode(out: &mut [u8], a: &[u64; NLIMBS]) {
    debug_assert!(out.len() >= ENCODED_BYTES);
    let mut c = [0u64; NLIMBS];
    redc(&mut c, a);
    for byte in out.iter_mut().take(ENCODED_BYTES) {
        *byte = (c[0] & 0xff) as u8;
        let _ = modshr(&mut c, 8);
    }
}

/// Decode `ENCODED_BYTES` canonical little-endian bytes. Returns all-ones
/// if the value was in `[0, p)`, else zero with `out` zeroed.
#[inline]
pub(crate) fn fp_decode(out: &mut [u64; NLIMBS], bytes: &[u8]) -> u32 {
    *out = [0; NLIMBS];
    if bytes.len() < ENCODED_BYTES {
        return 0;
    }
    for i in (0..ENCODED_BYTES).rev() {
        modshl(out, 8);
        out[0] = out[0].wrapping_add(bytes[i] as u64);
    }
    let ok = 0u64.wrapping_sub(modfsb(out) as u64);
    let canonical = *out;
    nres(out, &canonical);
    for limb in out.iter_mut() {
        *limb &= ok;
    }
    ok as u32
}

/// Bytes consumed per step of [`fp_decode_reduce`]. One byte short of the
/// encoding length, so every chunk is below `p` and decodes without
/// reduction.
const CHUNK_BYTES: usize = ENCODED_BYTES - 1;

/// Decode a little-endian byte string of any length modulo `p`. Never
/// fails; used to map hash output into the field.
#[inline]
pub(crate) fn fp_decode_reduce(out: &mut [u64; NLIMBS], bytes: &[u8]) {
    *out = [0; NLIMBS];
    let mut len = bytes.len();
    let rem = len % CHUNK_BYTES;
    if rem != 0 {
        let mut tmp = [0u8; ENCODED_BYTES];
        tmp[..rem].copy_from_slice(&bytes[len - rem..]);
        let _ = fp_decode(out, &tmp);
        len -= rem;
    }
    while len > 0 {
        len -= CHUNK_BYTES;
        mul_assign(out, &CHUNK_R);
        let mut tmp = [0u8; ENCODED_BYTES];
        tmp[..CHUNK_BYTES].copy_from_slice(&bytes[len..len + CHUNK_BYTES]);
        let mut chunk = [0u64; NLIMBS];
        let _ = fp_decode(&mut chunk, &tmp);
        let acc = *out;
        modadd(out, &acc, &chunk);
    }
}

type Limbs = Array<u64, <P664_17 as crate::params::Prime>::FpLimbs>;

#[inline]
fn as_arr(a: &Limbs) -> &[u64; NLIMBS] {
    <&[u64; NLIMBS]>::try_from(&a[..]).expect("invariant: FpLimbs == NLIMBS")
}

#[inline]
fn as_arr_mut(a: &mut Limbs) -> &mut [u64; NLIMBS] {
    <&mut [u64; NLIMBS]>::try_from(&mut a[..]).expect("invariant: FpLimbs == NLIMBS")
}

#[cfg(not(target_arch = "x86_64"))]
impl FpBackend for P664_17 {
    #[inline]
    fn set_zero(out: &mut Limbs) {
        *as_arr_mut(out) = ZERO;
    }

    #[inline]
    fn set_one(out: &mut Limbs) {
        *as_arr_mut(out) = ONE;
    }

    #[inline]
    fn set_small(out: &mut Limbs, val: u64) {
        modint(as_arr_mut(out), val);
    }

    #[inline]
    fn is_equal(a: &Limbs, b: &Limbs) -> Choice {
        Choice::from(modcmp(as_arr(a), as_arr(b)) as u8)
    }

    #[inline]
    fn is_zero(a: &Limbs) -> Choice {
        Choice::from(modis0(as_arr(a)) as u8)
    }

    #[inline]
    fn copy(out: &mut Limbs, a: &Limbs) {
        *as_arr_mut(out) = *as_arr(a);
    }

    #[inline]
    fn add(out: &mut Limbs, a: &Limbs, b: &Limbs) {
        modadd(as_arr_mut(out), as_arr(a), as_arr(b));
    }

    #[inline]
    fn sub(out: &mut Limbs, a: &Limbs, b: &Limbs) {
        modsub(as_arr_mut(out), as_arr(a), as_arr(b));
    }

    #[inline]
    fn neg(out: &mut Limbs, a: &Limbs) {
        modneg(as_arr_mut(out), as_arr(a));
    }

    #[inline]
    fn mul(out: &mut Limbs, a: &Limbs, b: &Limbs) {
        modmul(as_arr_mut(out), as_arr(a), as_arr(b));
    }

    #[inline]
    fn sqr(out: &mut Limbs, a: &Limbs) {
        modsqr(as_arr_mut(out), as_arr(a));
    }

    #[inline]
    fn inv(out: &mut Limbs, a: &Limbs) {
        let a = *as_arr(a);
        modinv(as_arr_mut(out), &a, None);
    }

    #[inline]
    fn sqrt(out: &mut Limbs, a: &Limbs) {
        let a = *as_arr(a);
        modsqrt(as_arr_mut(out), &a, None);
    }

    #[inline]
    fn is_square(a: &Limbs) -> Choice {
        Choice::from(modqr(as_arr(a), None) as u8)
    }

    #[inline]
    fn half(out: &mut Limbs, a: &Limbs) {
        modmul(as_arr_mut(out), &TWO_INV, as_arr(a));
    }

    #[inline]
    fn div3(out: &mut Limbs, a: &Limbs) {
        modmul(as_arr_mut(out), &THREE_INV, as_arr(a));
    }

    #[inline]
    fn exp3div4(out: &mut Limbs, a: &Limbs) {
        let a = *as_arr(a);
        modpro(as_arr_mut(out), &a);
    }

    #[inline]
    fn mul_small(out: &mut Limbs, a: &Limbs, val: u32) {
        modmli(as_arr_mut(out), as_arr(a), val as u64);
    }

    #[inline]
    fn encode(out: &mut [u8], a: &Limbs) {
        fp_encode(out, as_arr(a));
    }

    #[inline]
    fn decode(out: &mut Limbs, bytes: &[u8]) -> Choice {
        Choice::from((fp_decode(as_arr_mut(out), bytes) & 1) as u8)
    }

    #[inline]
    fn decode_reduce(out: &mut Limbs, bytes: &[u8]) {
        fp_decode_reduce(as_arr_mut(out), bytes);
    }

    #[inline]
    fn cswap(a: &mut Limbs, b: &mut Limbs, ctl: Choice) {
        modcsw(ctl.unwrap_u8() as u64, as_arr_mut(a), as_arr_mut(b));
    }

    #[inline]
    fn select(out: &mut Limbs, a0: &Limbs, a1: &Limbs, ctl: Choice) {
        let cw = 0u64.wrapping_sub(ctl.unwrap_u8() as u64);
        let a0 = as_arr(a0);
        let a1 = as_arr(a1);
        let out = as_arr_mut(out);
        for i in 0..NLIMBS {
            out[i] = a0[i] ^ (cw & (a0[i] ^ a1[i]));
        }
    }
}
